// capabilities are sent in an event sequence after the
// wp_tablet_seat.pad_added event before any actual events from this pad.
// This initial event sequence is terminated by a wp_tablet_pad.done event.
// All pad features (buttons, rings and strips) are logically divided into
// groups and all pads have at least one group. The available groups are
// notified through the wp_tablet_pad.group event; the compositor will emit
// one event per group before emitting wp_tablet_pad.done. Groups may have
// multiple modes. Modes allow clients to map multiple actions to a single
// pad feature. Only one mode can be active per group, although different
// groups may have different active modes.
pub struct ZwpTabletPadV2 {
	wayland.Object
}

// zwp_tablet_pad_v2_proxy wraps an object id in a ZwpTabletPadV2 proxy.
pub fn zwp_tablet_pad_v2_proxy(conn &wayland.Connection, id u32) ZwpTabletPadV2 {
	return ZwpTabletPadV2{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'zwp_tablet_pad_v2'
		}
	}
}

// ZwpTabletPadV2Listener receives the events of a zwp_tablet_pad_v2 object.
pub interface ZwpTabletPadV2Listener {
	// Sent on wp_tablet_pad initialization to announce available groups. One
	// event is sent for each pad group available. This event is sent in the
	// initial burst of events before the wp_tablet_pad.done event. At least one
	// group will be announced.
mut:
	group(proxy ZwpTabletPadV2, pad_group ZwpTabletPadGroupV2)
	// A system-specific device path that indicates which device is behind this
	// wp_tablet_pad. This information may be used to gather additional
	// information about the device, e.g. through libwacom. The format of the
	// path is unspecified, it may be a device node, a sysfs path, or some other
	// identifier. It is up to the client to identify the string provided. This
	// event is sent in the initial burst of events before the wp_tablet_pad.done
	// event.
	path(proxy ZwpTabletPadV2, path string)
	// Sent on wp_tablet_pad initialization to announce the available buttons.
	// This event is sent in the initial burst of events before the
	// wp_tablet_pad.done event. This event is only sent when at least one button
	// is available.
	buttons(proxy ZwpTabletPadV2, buttons u32)
	// This event signals the end of the initial burst of descriptive events. A
	// client may consider the static description of the pad to be complete and
	// finalize initialization of the pad.
	done(proxy ZwpTabletPadV2)
	// Sent whenever the physical state of a button changes.
	button(proxy ZwpTabletPadV2, time u32, button u32, state u32)
	// Notification that this pad is focused on the specified surface.
	enter(proxy ZwpTabletPadV2, serial u32, tablet ZwpTabletV2, surface wl.WlSurface)
	// Notification that this pad is no longer focused on the specified surface.
	leave(proxy ZwpTabletPadV2, serial u32, surface wl.WlSurface)
	// Sent when the pad has been removed from the system. When a tablet is
	// removed its pad(s) will be removed too. When this event is received, the
	// client must destroy all rings, strips and groups that were offered by this
	// pad, and issue wp_tablet_pad.destroy the pad itself.
	removed(proxy ZwpTabletPadV2)
}

// NoopZwpTabletPadV2Listener ignores every zwp_tablet_pad_v2 event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopZwpTabletPadV2Listener {}

pub fn (mut listener NoopZwpTabletPadV2Listener) group(_proxy ZwpTabletPadV2, _pad_group ZwpTabletPadGroupV2) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) path(_proxy ZwpTabletPadV2, _path string) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) buttons(_proxy ZwpTabletPadV2, _buttons u32) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) done(_proxy ZwpTabletPadV2) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) button(_proxy ZwpTabletPadV2, _time u32, _button u32, _state u32) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) enter(_proxy ZwpTabletPadV2, _serial u32, _tablet ZwpTabletV2, _surface wl.WlSurface) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) leave(_proxy ZwpTabletPadV2, _serial u32, _surface wl.WlSurface) {
}

pub fn (mut listener NoopZwpTabletPadV2Listener) removed(_proxy ZwpTabletPadV2) {
}

struct ZwpTabletPadV2Sink {
mut:
	proxy    ZwpTabletPadV2
	listener ZwpTabletPadV2Listener = NoopZwpTabletPadV2Listener{}
}

fn (mut s ZwpTabletPadV2Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			pad_group_id := msg.arg_id(0)!
			s.proxy.conn.register_object(pad_group_id, 'zwp_tablet_pad_group_v2', &zwp_tablet_pad_group_v2_desc)!
			pad_group := zwp_tablet_pad_group_v2_proxy(s.proxy.conn, pad_group_id)
			s.listener.group(s.proxy, pad_group)
		}
		1 {
			path := msg.arg_string(0)!
			s.listener.path(s.proxy, path)
		}
		2 {
			buttons := msg.arg_u32(0)!
			s.listener.buttons(s.proxy, buttons)
		}
		3 {
			s.listener.done(s.proxy)
		}
		4 {
			time := msg.arg_u32(0)!
			button := msg.arg_u32(1)!
			state := msg.arg_u32(2)!
			s.listener.button(s.proxy, time, button, state)
		}
		5 {
			serial := msg.arg_u32(0)!
			tablet_id := msg.arg_id(1)!
			tablet := zwp_tablet_v2_proxy(s.proxy.conn, tablet_id)
			surface_id := msg.arg_id(2)!
			surface := wl.wl_surface_proxy(s.proxy.conn, surface_id)
			s.listener.enter(s.proxy, serial, tablet, surface)
		}
		6 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl.wl_surface_proxy(s.proxy.conn, surface_id)
			s.listener.leave(s.proxy, serial, surface)
		}
		7 {
			s.listener.removed(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives zwp_tablet_pad_v2 events.
pub fn (proxy &ZwpTabletPadV2) set_listener(listener ZwpTabletPadV2Listener) ! {
	proxy.conn.set_sink(proxy.id, ZwpTabletPadV2Sink{
		proxy:    *proxy
		listener: listener
	})!
}

// Requests the compositor to use the provided feedback string associated
// with this button. This request should be issued immediately after a
// wp_tablet_pad_group.mode_switch event from the corresponding group is
// received, or whenever a button is mapped to a different action. See
// wp_tablet_pad_group.mode_switch for more details. Clients are encouraged
// to provide context-aware descriptions for the actions associated with each
// button, and compositors may use this information to offer visual feedback
// on the button layout (e.g. on-screen displays). Button indices start at 0.
// Setting the feedback string on a button that is reserved by the compositor
// (i.e. not belonging to any wp_tablet_pad_group) does not generate an error
// but the compositor is free to ignore the request. The provided string
// 'description' is a UTF-8 encoded string to be associated with this ring,
// and is considered user-visible; general internationalization rules apply.
// The serial argument will be that of the last
// wp_tablet_pad_group.mode_switch event received for the group of this
// button. Requests providing other serials than the most recent one will be
// ignored.
pub fn (proxy &ZwpTabletPadV2) set_feedback(button u32, description string, serial u32) ! {
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(button), wayland.ArgValue(description),
		wayland.ArgValue(serial)])!
}

// Destroy the wp_tablet_pad object. Objects created from this object are
// unaffected and should be destroyed separately.
pub fn (proxy &ZwpTabletPadV2) destroy() ! {
	proxy.conn.request(proxy.id, 1, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// zwp_tablet_pad_v2.button_state: values of the zwp_tablet_pad_v2 protocol enum.
// the button is not pressed
pub const zwp_tablet_pad_v2_button_state_released = u32(0)
// the button is pressed
pub const zwp_tablet_pad_v2_button_state_pressed = u32(1)

// bind_zwp_tablet_manager_v2 binds the zwp_tablet_manager_v2 global to a typed proxy.
pub fn bind_zwp_tablet_manager_v2(conn &wayland.Connection, global wayland.Global) !ZwpTabletManagerV2 {
	version := if global.version < zwp_tablet_manager_v2_desc.version {
		global.version
	} else {
		zwp_tablet_manager_v2_desc.version
	}
	object := conn.bind_global(global, 'zwp_tablet_manager_v2', version, &zwp_tablet_manager_v2_desc)!
	return ZwpTabletManagerV2{
		Object: object
	}
}
